def is_woodall(n):
    """
    Check if a number is a Woodall number.
    A Woodall number is of the form k * 2^k - 1 where k is a positive integer.
    """
    if n < 0:
        return False

    # Check for each possible k value
    # Since k * 2^k - 1 grows quickly, we don't need to check very far
    k = 1
    while True:
        woodall = k * (2 ** k) - 1
        if woodall == n:
            return True
        if woodall > n:
            return False
        k += 1
        # Safety limit to avoid infinite loops
        if k > 100:
            return False

